           DB_NAME: ${{ steps.get-db.outputs.database_name }}
           BUCKET_NAME: ${{ steps.create-r2.outputs.bucket_name }}
           ACHIEVEMENT_QUEUE_NAME: ${{ steps.create-queue.outputs.achievement_queue_name }}
           SEED_QUEUE_NAME: ${{ steps.create-queue.outputs.seed_queue_name }}

       - name: 🔄 Run Database Migrations
         run: |
           bun wrangler d1 migrations apply DB --remote --config wrangler.preview.jsonc
         env:
           CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
           CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}

       - name: 🌱 Seed Database
         run: bun run db:seed:remote
         working-directory: apps/worker
         env:
           CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
           CLOUDFLARE_DATABASE_ID: ${{ steps.get-db.outputs.database_id }}
           CLOUDFLARE_D1_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}

       - name: 🔐 Set BETTER_AUTH_SECRET
         run: bun run .github/scripts/preview/set-better-auth-secret.ts
         env:
           WORKER_NAME: ${{ steps.prepare-config.outputs.worker_name }}
           CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
           CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
           GITHUB_CLIENT_SECRET: ${{ secrets.GITHUB_CLIENT_SECRET }}

       - name: 🔐 Set SEED_ALLOWED
         run: |
           printf "y\ntrue" | bun wrangler secret put SEED_ALLOWED --name ${{ steps.prepare-config.outputs.worker_name }}
         env:
           CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
           CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}

