             const dbName = '${{ steps.get-db.outputs.database_name }}';

             const bucketName = '${{ steps.create-r2.outputs.bucket_name }}';
             const achievementQueueName = '${{ steps.create-queue.outputs.achievement_queue_name }}';
             const seedQueueName = '${{ steps.create-queue.outputs.seed_queue_name }}';
             const comment = `## 🚀 Preview Environment Deployed

             **Preview URL:** <a href="${previewUrl}" target="_blank">${previewUrl}</a>
             **Database:** \`${dbName}\`
             **R2 Buckets:** \`${bucketName}\`
             **Queues:** \`${achievementQueueName}\`, \`${seedQueueName}\`

             **Test Account:**
             - Email: \`seed@scorebrawl.com\`
             - Password: \`Test.1234\`

             This preview environment will be automatically cleaned up when the PR is closed.`;

             // Find existing comment
             const { data: comments } = await github.rest.issues.listComments({
               owner: context.repo.owner,
               repo: context.repo.repo,
               issue_number: prNumber,
             });

             const botComment = comments.find(comment =>
               comment.user.type === 'Bot' &&
               comment.body.includes('Preview Environment Deployed')
             );

             if (botComment) {
               await github.rest.issues.updateComment({
                 owner: context.repo.owner,
                 repo: context.repo.repo,
                 comment_id: botComment.id,
                 body: comment
               });
             } else {
               await github.rest.issues.createComment({
                 owner: context.repo.owner,
                 repo: context.repo.repo,
                 issue_number: prNumber,
                 body: comment
               });
             }

   cleanup-preview:
     if: github.event.action == 'closed'
     runs-on: blacksmith-4vcpu-ubuntu-2404
-    timeout-minutes: 15
     permissions:
       contents: read
       pull-requests: write
     steps:
       - name: 📥 Checkout
         uses: actions/checkout@08c6903cd8c0fde910a37f88322edcfb5dd907a8 #v5.0.0

       - name: 🥟 Setup Bun
-        uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2.2.0
+        uses: oven-sh/setup-bun@735343b667d3e6f658f44d0eca948eb6282f2b76 # v2.0.2
         with:
           bun-version: latest

-      - name: Setup Node.js 22.x
-        uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
-        with:
-          node-version: 22.x
-
       - name: 📦 Install dependencies
         run: bun install

       - name: 🗑️ Remove Worker as Queue Consumer
         continue-on-error: true
         run: bun run .github/scripts/preview/remove-queue-consumer.ts
         env:
           PR_NUMBER: ${{ github.event.pull_request.number }}
           CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
           CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}

       - name: 🗑️ Delete Worker
-        uses: cloudflare/wrangler-action@ebbaa1584979971c8614a24965b4405ff95890e0 # v4.0.0
+        uses: cloudflare/wrangler-action@v3
