 											disabled={hasMatches}
 											className="h-8 font-mono focus:border-amber-500 focus:ring-amber-500/20 text-sm disabled:opacity-50"
 										/>
 										{errors.kFactor?.message && (
 											<p className="text-destructive text-xs font-mono mt-0.5">
 												{errors.kFactor.message}
