 									<FieldLabel className="font-mono text-xs font-medium tracking-wide mb-0.5">
 										Rounds
 									</FieldLabel>
 									<Input
 										{...register("rounds", { valueAsNumber: true })}
 										type="number"
 										disabled={hasMatches}
 										placeholder="1"
 										className="h-8 font-mono focus:border-blue-500 focus:ring-blue-500/20 text-sm disabled:opacity-50"
 									/>
 									{errors.rounds?.message && (
 										<p className="text-destructive text-xs font-mono mt-0.5">
 											{errors.rounds.message}
 										</p>
 									)}
 								</Field>
 							)}
 						</FieldGroup>

 						{/* Error Display */}
 						{apiError && (
 							<div className="rounded-lg bg-destructive/10 border border-destructive/20 p-3">
 								<p className="text-destructive font-mono text-xs">{apiError}</p>
 							</div>
 						)}

 						{/* Action Buttons */}
 						<div className="flex gap-4 pt-2">
 							<Button
 								type="button"
 								variant="outline"
 								onClick={handleCancel}
 								className="font-mono h-8 text-sm"
 							>
 								Cancel
 							</Button>
 							<GlowButton
 								type="submit"
 								glowColor={glowColors.blue}
 								disabled={!canSubmit}
 								className="flex-1 font-mono h-8 text-sm"
 							>
 								{editMutation.isPending ? "Saving..." : "Save Changes"}
 							</GlowButton>
 						</div>
 					</form>
 				</div>
 			</DialogContent>
 		</Dialog>
 	);
 }

