 			name: playerDataMap.get(id)?.name || "",
 		}));

 		// Calculate ELO scores
 		const eloResult = calculateMatchResult({
 			seasonData,
 			homeScore: input.homeScore,
 			awayScore: input.awayScore,
 			homePlayers,
