 			});

 			const sessionInfo = await getSessionForOrg(
 				ctx.db,
 				result.resolved.sessionId,
 				ctx.organizationId
 			);

 			ctx.waitUntil(
 				broadcastSeasonEvent(ctx.env, ctx.organization.slug, sessionInfo.seasonSlug, {
 					type: "session:update",
