 		status: "playing",
 		queuePosition: 0,
 		consecutiveGames: 1,
 		...overrides,
 	};
 }

 function waiter(id: string, queuePosition: number, consecutiveGames = 0): SessionPlayerState {
 	return makePlayer(id, {
 		status: "waiting",
 		queuePosition,
 		consecutiveGames,
 	});
 }

 function base(overrides: Partial<WinnerStaysRotationInput> = {}): WinnerStaysRotationInput {
 	return {
